/*global todoify */
(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  // -----------------------------------------------------------------------
  // Model
  // -----------------------------------------------------------------------

  var todoModel = {
    // Load from localStorage
    load: function () {
      try {
        var data = localStorage.getItem(STORAGE_KEY);
        return data ? JSON.parse(data) : [];
      } catch (e) {
        return [];
      }
    },

    // Save to localStorage
    save: function (todos) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    },

    // Generate a unique id
    uid: function () {
      return Date.now() + Math.random().toString(36).slice(2, 7);
    }
  };

  // -----------------------------------------------------------------------
  // App
  // -----------------------------------------------------------------------

  var app = {
    todos: [],
    filter: 'all',

    // DOM refs
    $newTodo: null,
    $main: null,
    $footer: null,
    $toggleAll: null,
    $todoList: null,
    $todoCount: null,
    $clearCompleted: null,
    $filters: null,

    // Init
    init: function () {
      this.$newTodo = document.querySelector('.new-todo');
      this.$main = document.querySelector('.main');
      this.$footer = document.querySelector('.footer');
      this.$toggleAll = document.getElementById('toggle-all');
      this.$todoList = document.querySelector('.todo-list');
      this.$todoCount = document.querySelector('.todo-count');
      this.$clearCompleted = document.querySelector('.clear-completed');
      this.$filters = document.querySelector('.filters');

      this.todos = todoModel.load();
      this.bindEvents();
      this.filter = this.getFilterFromHash();
      this.render();
    },

    // Get filter from URL hash
    getFilterFromHash: function () {
      var hash = window.location.hash.replace('#/', '') || 'all';
      if (hash === 'all' || hash === 'active' || hash === 'completed') {
        return hash;
      }
      return 'all';
    },

    // Bind all events
    bindEvents: function () {
      var self = this;

      // New todo
      this.$newTodo.addEventListener('change', function () {
        self.addTodo();
      });
      this.$newTodo.addEventListener('keydown', function (e) {
        if (e.keyCode === ENTER_KEY) {
          self.addTodo();
        }
      });

      // Toggle all
      this.$toggleAll.addEventListener('change', function () {
        self.toggleAll(this.checked);
      });

      // Clear completed
      this.$clearCompleted.addEventListener('click', function () {
        self.clearCompleted();
      });

      // Routing
      window.addEventListener('hashchange', function () {
        self.filter = self.getFilterFromHash();
        self.render();
      });

      // --- Event delegation on todo-list (survives re-renders) ---

      // Toggle individual todo
      this.$todoList.addEventListener('change', function (e) {
        if (e.target.classList.contains('toggle')) {
          var li = e.target.closest('li');
          if (li) {
            self.toggleTodo(li.getAttribute('data-id'));
          }
        }
      });

      // Destroy todo
      this.$todoList.addEventListener('click', function (e) {
        if (e.target.classList.contains('destroy')) {
          var li = e.target.closest('li');
          if (li) {
            self.destroyTodo(li.getAttribute('data-id'));
          }
        }
      });

      // Double-click label to edit
      this.$todoList.addEventListener('dblclick', function (e) {
        if (e.target.tagName === 'LABEL') {
          var li = e.target.closest('li');
          if (li) {
            self.editMode(li, li.getAttribute('data-id'));
          }
        }
      });
    },

    // Add a new todo
    addTodo: function () {
      var title = this.$newTodo.value.trim();
      if (title === '') {
        this.$newTodo.value = '';
        return;
      }

      this.todos.push({
        id: todoModel.uid(),
        title: title,
        completed: false
      });

      this.$newTodo.value = '';
      this.saveAndRender();
    },

    // Toggle a todo's completed state
    toggleTodo: function (id) {
      for (var i = 0; i < this.todos.length; i++) {
        if (this.todos[i].id === id) {
          this.todos[i].completed = !this.todos[i].completed;
          break;
        }
      }
      this.saveAndRender();
    },

    // Toggle all todos
    toggleAll: function (checked) {
      for (var i = 0; i < this.todos.length; i++) {
        this.todos[i].completed = checked;
      }
      this.saveAndRender();
    },

    // Delete a todo
    destroyTodo: function (id) {
      var todos = [];
      for (var i = 0; i < this.todos.length; i++) {
        if (this.todos[i].id !== id) {
          todos.push(this.todos[i]);
        }
      }
      this.todos = todos;
      this.saveAndRender();
    },

    // Clear completed todos
    clearCompleted: function () {
      var todos = [];
      for (var i = 0; i < this.todos.length; i++) {
        if (!this.todos[i].completed) {
          todos.push(this.todos[i]);
        }
      }
      this.todos = todos;
      this.saveAndRender();
    },

    // Save edit
    editTodo: function (id, title) {
      var trimmed = title.trim();
      if (trimmed === '') {
        this.destroyTodo(id);
        return;
      }
      for (var i = 0; i < this.todos.length; i++) {
        if (this.todos[i].id === id) {
          this.todos[i].title = trimmed;
          break;
        }
      }
      this.saveAndRender();
    },

    // Save and render
    saveAndRender: function () {
      todoModel.save(this.todos);
      this.render();
    },

    // Get filtered todos
    getFilteredTodos: function () {
      if (this.filter === 'active') {
        return this.todos.filter(function (t) { return !t.completed; });
      }
      if (this.filter === 'completed') {
        return this.todos.filter(function (t) { return t.completed; });
      }
      return this.todos;
    },

    // Count active todos
    activeCount: function () {
      var count = 0;
      for (var i = 0; i < this.todos.length; i++) {
        if (!this.todos[i].completed) count++;
      }
      return count;
    },

    // Count completed todos
    completedCount: function () {
      var count = 0;
      for (var i = 0; i < this.todos.length; i++) {
        if (this.todos[i].completed) count++;
      }
      return count;
    },

    // Render the entire view
    render: function () {
      var self = this;
      var filtered = this.getFilteredTodos();
      var activeCount = this.activeCount();
      var completedCount = this.completedCount();

      // Show/hide main and footer
      var hasTodos = this.todos.length > 0;
      this.$main.style.display = hasTodos ? 'block' : 'none';
      this.$footer.style.display = hasTodos ? 'block' : 'none';

      // Toggle all checkbox
      this.$toggleAll.checked = activeCount === 0 && this.todos.length > 0;

      // Clear completed button
      this.$clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';

      // Render todo list
      var html = '';
      for (var i = 0; i < filtered.length; i++) {
        var todo = filtered[i];
        var liClass = '';
        if (todo.completed) liClass += ' completed';
        html += '<li' + (liClass ? ' class="' + liClass.trim() + '"' : '') + ' data-id="' + todo.id + '">';
        html += '  <div class="view">';
        html += '    <input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>';
        html += '    <label>' + self.escapeHtml(todo.title) + '</label>';
        html += '    <button class="destroy"></button>';
        html += '  </div>';
        html += '  <input class="edit" value="' + self.escapeHtml(todo.title) + '">';
        html += '</li>';
      }
      this.$todoList.innerHTML = html;

      // Update count
      var itemWord = activeCount === 1 ? 'item' : 'items';
      this.$todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + itemWord + ' left';

      // Update filter links
      var filterLinks = this.$filters.querySelectorAll('a');
      for (var j = 0; j < filterLinks.length; j++) {
        var a = filterLinks[j];
        var href = a.getAttribute('href');
        var filterName = href.replace('#/', '') || 'all';
        if (filterName === '') filterName = 'all';
        if (filterName === this.filter) {
          a.classList.add('selected');
        } else {
          a.classList.remove('selected');
        }
      }

    },

    // Enter editing mode
    editMode: function (li, id) {
      var self = this;
      li.classList.add('editing');

      var editInput = li.querySelector('.edit');
      editInput.focus();
      editInput.value = li.querySelector('label').textContent;

      // Save on blur
      var onBlur = function () {
        self.editTodo(id, editInput.value);
        li.classList.remove('editing');
        editInput.removeEventListener('blur', onBlur);
        editInput.removeEventListener('keydown', onKeydown);
      };

      // Save on enter, discard on escape
      var onKeydown = function (e) {
        if (e.keyCode === ENTER_KEY) {
          editInput.blur();
        } else if (e.keyCode === ESCAPE_KEY) {
          editInput.value = li.querySelector('label').textContent;
          li.classList.remove('editing');
          editInput.removeEventListener('blur', onBlur);
          editInput.removeEventListener('keydown', onKeydown);
        }
      };

      editInput.addEventListener('blur', onBlur);
      editInput.addEventListener('keydown', onKeydown);
    },

    // Escape HTML for safe rendering
    escapeHtml: function (text) {
      var div = document.createElement('div');
      div.appendChild(document.createTextNode(text));
      return div.innerHTML;
    }
  };

  // -----------------------------------------------------------------------
  // Boot
  // -----------------------------------------------------------------------

  app.init();
})();

